import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_riverpod/legacy.dart';
import 'package:flutter_svg/svg.dart';

import '../../themes/stack_colors.dart';
import '../../utilities/assets.dart';
import 'settings_menu_item.dart';

/// The desktop settings pages, in menu order. The selected one is
/// [selectedSettingsMenuItemStateProvider] (its index).
enum DesktopSettingsPage {
  backupRestore("Backup and restore"),
  security("Security"),
  currency("Currency"),
  tor("Tor settings"),
  nodes("Manage nodes"),
  startup("Startup"),
  appearance("Appearance"),
  syncing("Syncing preferences"),
  advanced("Advanced");

  const DesktopSettingsPage(this.label);
  final String label;
}

final selectedSettingsMenuItemStateProvider = StateProvider<int>((_) => 0);

class SettingsMenu extends ConsumerStatefulWidget {
  const SettingsMenu({super.key});

  @override
  ConsumerState<ConsumerStatefulWidget> createState() => _SettingsMenuState();
}

class _SettingsMenuState extends ConsumerState<SettingsMenu> {
  @override
  Widget build(BuildContext context) {
    debugPrint("BUILD: $runtimeType");

    final labels = [for (final page in DesktopSettingsPage.values) page.label];

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        SizedBox(
          width: 250,
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              for (int i = 0; i < labels.length; i++)
                Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    if (i > 0) const SizedBox(height: 2),
                    SettingsMenuItem<int>(
                      icon: SvgPicture.asset(
                        Assets.svg.polygon,
                        width: 11,
                        height: 11,
                        color:
                            ref.watch(selectedSettingsMenuItemStateProvider) ==
                                i
                            ? Theme.of(context)
                                  .extension<StackColors>()!
                                  .accentColorBlue
                            : Colors.transparent,
                      ),
                      label: labels[i],
                      value: i,
                      group: ref.watch(selectedSettingsMenuItemStateProvider),
                      onChanged: (newValue) =>
                          ref
                                  .read(
                                    selectedSettingsMenuItemStateProvider
                                        .notifier,
                                  )
                                  .state =
                              newValue,
                    ),
                  ],
                ),
            ],
          ),
        ),
      ],
    );
  }
}
